import Foundation
import XCTest
@testable import fearless

/// Cross-check vectors produced by the web wallet's Iroha Connect v1 implementation (fearless-wallet-web PR #1122,
/// branch `feature/iroha-connect-current`, `iroha-connect-service/wire.ts`, `transactionReview.ts` and the
/// service) talking to the upstream `@iroha/iroha-js` 0.0.3 app SDK. Regenerate with the harness in
/// `build/reports/ios-iroha-connect-v1-20261121/vectors/` (see `docs/irohaconnect-safe-signing.md`).
enum IrohaConnectWebVectors {
    static let root: [String: Any] = {
        guard let object = try? JSONSerialization.jsonObject(with: Data(json.utf8)) as? [String: Any] else {
            fatalError("IrohaConnect web vectors are not valid JSON")
        }
        return object
    }()

    static func section(_ name: String) -> [String: Any] {
        root[name] as? [String: Any] ?? [:]
    }

    static func string(_ section: String, _ key: String) -> String {
        self.section(section)[key] as? String ?? ""
    }

    static func bytes(_ section: String, _ key: String) -> Data {
        Data(irohaConnectHex: string(section, key)) ?? Data()
    }

    static var transcript: [(direction: String, frame: Data, note: String?)] {
        let entries = section("session")["transcript"] as? [[String: Any]] ?? []
        return entries.map { entry in
            (
                entry["dir"] as? String ?? "",
                Data(irohaConnectHex: entry["hex"] as? String ?? "") ?? Data(),
                entry["note"] as? String
            )
        }
    }

    static var sessionAccount: IrohaConnectAccountDescriptor {
        let account = section("session")["account"] as? [String: Any] ?? [:]
        return IrohaConnectAccountDescriptor(
            walletName: "Vectors",
            accountID: account["accountId"] as? String ?? "",
            publicKey: Data(irohaConnectHex: account["publicKeyHex"] as? String ?? "") ?? Data()
        )
    }

    static var sessionLink: IrohaConnectWalletURI {
        // swiftlint:disable:next force_try
        try! IrohaConnectWalletURI.parse(string("session", "uri"))
    }

    /// The iOS review of one of the web's transaction vectors (for prompt and coordinator tests).
    static func reviewedTransaction(_ name: String) -> IrohaConnectReviewedTransaction {
        let cases = root["transactions"] as? [[String: Any]] ?? []
        let entry = cases.first { $0["name"] as? String == name } ?? [:]
        let json = entry["expectation"] as? [String: Any] ?? [:]
        let expectation = IrohaConnectTransactionExpectation(
            networkID: (try? IrohaConnectNetworkID.parse(json["networkId"] as? String ?? "")) ?? .taira,
            networkPrefix: json["networkPrefix"] as? Int ?? IrohaConnectProfile.taira.networkPrefix,
            authority: json["authority"] as? String ?? "",
            signingPublicKey: Data(irohaConnectHex: json["signingPublicKeyHex"] as? String ?? "") ?? Data()
        )
        // swiftlint:disable:next force_try
        return try! IrohaConnectTransactionReviewer.review(
            Data(irohaConnectHex: entry["payloadHex"] as? String ?? "") ?? Data(),
            expectation: expectation
        )
    }

    /// The 64 signature bytes inside an element-framed approve frame (its last 64 x 9 bytes).
    static func approveSignature(_ frame: Data) -> Data {
        let bytes = [UInt8](frame)
        let start = bytes.count - 64 * 9
        return Data((0 ..< 64).map { bytes[start + $0 * 9 + 8] })
    }

