/// An in-memory relay socket: records what the wallet sends and lets a test deliver frames.
final class IrohaConnectFakeTransport: IrohaConnectTransport {
    var onOpen: ((String?) -> Void)?
    var onMessage: ((Data) -> Void)?
    var onTextMessage: (() -> Void)?
    var onClose: ((Error?) -> Void)?

    private let lock = NSLock()
    private var storedSent: [Data] = []
    private(set) var openCount = 0
    private(set) var closeCount = 0
    var sendError: Error?

    var sent: [Data] {
        lock.lock()
        defer { lock.unlock() }
        return storedSent
    }

    func open() {
        openCount += 1
    }

    func send(_ data: Data, completion: @escaping (Error?) -> Void) {
        lock.lock()
        storedSent.append(data)
        lock.unlock()
        completion(sendError)
    }

    func close() {
        closeCount += 1
    }
}

/// Signs with fixed signatures, so wallet frames can be compared byte for byte with the web wallet's.
final class IrohaConnectFixedSigner: IrohaConnectAccountProviding {
    let account: IrohaConnectAccountDescriptor
    var signatures: [Data: Data]
    private(set) var signedMessages: [Data] = []
    var selectionError: Error?

    init(account: IrohaConnectAccountDescriptor, signatures: [Data: Data] = [:]) {
        self.account = account
        self.signatures = signatures
    }

    func selectedAccount() throws -> IrohaConnectAccountDescriptor {
        if let selectionError { throw selectionError }
        return account
    }

    func sign(_ message: Data, for requested: IrohaConnectAccountDescriptor) throws -> Data {
        guard requested == account else { throw IrohaConnectAccountProviderError.accountMismatch }
        signedMessages.append(message)
        return signatures[message] ?? Data(repeating: 0x5A, count: 64)
    }
}
